// ─── Helpers ──────────────────────────────────────────────────────────────────

function loadScript(src: string): Promise<void> {
  return new Promise((resolve, reject) => {
    if (document.querySelector(`script[src="${src}"]`)) { resolve(); return; }
    const s = document.createElement('script');
    s.src = src;
    s.onload = () => resolve();
    s.onerror = reject;
    document.head.appendChild(s);
  });
}

function loadStyle(href: string): void {
  if (document.querySelector(`link[href="${href}"]`)) return;
  const l = document.createElement('link');
  l.rel = 'stylesheet';
  l.href = href;
  document.head.appendChild(l);
}

function buildPopup(sat: SatPosition): string {
  const color = SAT_CATEGORY_COLOR[sat.category];
  return `
    <div style="font-family: monospace; line-height: 1.8;">
      <div style="font-size: 14px; font-weight: 700; margin-bottom: 6px; color: ${color};">
        🛰 ${sat.name}
      </div>
      <table style="border-collapse: collapse; width: 100%;">
        <tr><td style="color:#8b949e; padding-right:12px; font-size:11px;">Lat</td>
            <td>${sat.latitude.toFixed(4)}°</td></tr>
        <tr><td style="color:#8b949e; padding-right:12px; font-size:11px;">Lon</td>
            <td>${sat.longitude.toFixed(4)}°</td></tr>
        <tr><td style="color:#8b949e; padding-right:12px; font-size:11px;">Altitude</td>
            <td>${sat.altitude.toFixed(1)} km</td></tr>
      </table>
    </div>
  `;
}

// ─── Component ────────────────────────────────────────────────────────────────

export default function SatelliteMap() {
  const mapElRef   = useRef<HTMLDivElement>(null);
  const mapRef     = useRef<import('leaflet').Map | null>(null);
  // ISS-specific refs (trail + footprint)
  const issMarkerRef    = useRef<import('leaflet').CircleMarker | null>(null);
  const trailLineRef    = useRef<import('leaflet').Polyline | null>(null);
  const footprintRef    = useRef<import('leaflet').Circle | null>(null);
  // Other satellite markers keyed by NORAD id
  const satMarkersRef   = useRef<Map<number, import('leaflet').CircleMarker>>(new Map());

  const [ready, setReady] = useState(false);

  const { data: issData }   = useISSPosition(5000);
  const allSats             = useSatellites(15000);
  const { trail, addPoint } = useOrbitTrail(80);

  // Load Leaflet
  useEffect(() => {
    loadStyle(LEAFLET_CSS);
    loadScript(LEAFLET_JS).then(() => setReady(true));
  }, []);

  // Init map once Leaflet is ready
  useEffect(() => {
    if (!ready || !mapElRef.current || mapRef.current) return;
    const L = window.L;

    const map = L.map(mapElRef.current, {
      center: [20, 0],
      zoom: 2,
      zoomControl: true,
      attributionControl: false,
      minZoom: 2,
    });

    L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', { maxZoom: 10 }).addTo(map);

    // ISS marker (larger, always on top)
    const issMarker = L.circleMarker([20, 0], {
      radius: 8,
      color: SAT_CATEGORY_COLOR.station,
      fillColor: SAT_CATEGORY_COLOR.station,
      fillOpacity: 1,
      weight: 2,
      pane: 'markerPane',
    }).addTo(map);
    issMarker.bindPopup('Loading ISS…', { maxWidth: 260, minWidth: 200 });
    issMarker.bindTooltip('🛰 ISS · International Space Station', { direction: 'top', offset: [0, -8] });
    issMarkerRef.current = issMarker;

    // Orbit trail
    const trail_ = L.polyline([], {
      color: `${SAT_CATEGORY_COLOR.station}55`,
      weight: 1.5,
      dashArray: '4 4',
    }).addTo(map);
    trailLineRef.current = trail_;

    // Footprint circle
    const footprint = L.circle([20, 0], {
      radius: 0,
      color: `${SAT_CATEGORY_COLOR.station}22`,
      fillColor: `${SAT_CATEGORY_COLOR.station}08`,
      fillOpacity: 1,
      weight: 1,
    }).addTo(map);
    footprintRef.current = footprint;

    mapRef.current = map;
    return () => {
      map.remove();
      mapRef.current = null;
      issMarkerRef.current = null;
      trailLineRef.current = null;
      footprintRef.current = null;
      satMarkersRef.current.clear();
    };
  }, [ready]);

  // Update ISS marker + trail + footprint
  useEffect(() => {
    if (!issData || !mapRef.current) return;
    const latlng: [number, number] = [issData.latitude, issData.longitude];
    addPoint(issData.latitude, issData.longitude);
    issMarkerRef.current?.setLatLng(latlng);
    issMarkerRef.current?.setPopupContent(
      buildPopup({ ...issData, norad: 25544, category: 'station', displayName: 'ISS' }),
    );
    footprintRef.current?.setLatLng(latlng);
    footprintRef.current?.setRadius((issData.footprint / 2) * 1000);
  }, [issData, addPoint]);

  // Update ISS trail
  useEffect(() => {
    trailLineRef.current?.setLatLngs(trail as [number, number][]);
  }, [trail]);

  // Update / create markers for all other satellites
  useEffect(() => {
    if (!mapRef.current || !window.L) return;
    const L = window.L;
    const map = mapRef.current;
    const existing = satMarkersRef.current;

    allSats.forEach((sat) => {
      if (sat.norad === 25544) return; // ISS handled separately
      const latlng: [number, number] = [sat.latitude, sat.longitude];
      const color = SAT_CATEGORY_COLOR[sat.category];

      const tooltipText = `🛰 ${sat.name} · ${sat.altitude.toFixed(0)} km`;

      if (existing.has(sat.norad)) {
        const m = existing.get(sat.norad)!;
        m.setLatLng(latlng);
        m.setPopupContent(buildPopup(sat));
        m.setTooltipContent(tooltipText);
      } else {
        const marker = L.circleMarker(latlng, {
          radius: 5,
          color,
          fillColor: color,
          fillOpacity: 0.85,
          weight: 1.5,
        }).addTo(map);
        marker.bindPopup(buildPopup(sat), { maxWidth: 260, minWidth: 200 });
        marker.bindTooltip(tooltipText, { direction: 'top', offset: [0, -6] });
        existing.set(sat.norad, marker);
      }
    });
  }, [allSats]);

  return (
    <Wrapper>
      <MapArea>
        <MapEl>
          <div ref={mapElRef} style={{ height: '100%', width: '100%' }} />
        </MapEl>
      </MapArea>

      <Legend>
        <LegendTitle>Legend</LegendTitle>
        {LEGEND_ITEMS.map(({ category, label, examples }) => (
          <LegendItem key={category}>
            <LegendDot color={SAT_CATEGORY_COLOR[category]} />
            {label}
            <LegendSub>· {examples}</LegendSub>
          </LegendItem>
        ))}
      </Legend>

      <StatusBar>
        <StatusDot live={!!issData} />
        <span>ISS</span>
        {issData && (
          <>
            <span>·</span>
            <span>{issData.latitude.toFixed(3)}°, {issData.longitude.toFixed(3)}°</span>
            <span>·</span>
            <span>{issData.altitude.toFixed(1)} km</span>
            <span>·</span>
            <span>{(issData.velocity / 3600).toFixed(2)} km/s</span>
          </>
        )}
        <span style={{ marginLeft: 'auto' }}>
          {allSats.length} satellites tracked · click any marker for details
          &nbsp;·&nbsp;
          <a
            href="https://www.openstreetmap.org/copyright"
            target="_blank"
            rel="noopener noreferrer"
            style={{ color: 'inherit', textDecoration: 'underline', opacity: 0.7 }}
          >
            © OpenStreetMap contributors
          </a>
        </span>
      </StatusBar>
    </Wrapper>
  );
}
